const state = $getWorkflowStaticData('global');
state.processed ??= {};
state.initialized ??= false;

const fediBaseUrl = 'https://YOUR_FEDI_HOST';
const fediAccount = 'YOUR_USERNAME@YOUR_FEDI_HOST';
const atprotoHandle = 'YOUR_ATPROTO_HANDLE';

if ([fediBaseUrl, fediAccount, atprotoHandle].some(value => value.includes('YOUR_'))) {
  throw new Error('Replace all YOUR_* placeholders in the Configuration node before activating the workflow.');
}

return [{
  json: {
    fediBaseUrl: fediBaseUrl.replace(/\/$/, ''),
    fediAccount,
    fediUsername: fediAccount.split('@')[0],
    atprotoHandle,
    bootstrapMode: 'skip_existing',
    fetchLimit: 40,
    maxProcessedIds: 2000,
    language: 'de',
    imageMaxBytes: 1000000,
    imageMaxDimension: 1200,
    imageJpegQuality: 68,
  },
}];

const cfg = $('Configuration').first().json;
const state = $getWorkflowStaticData('global');
state.processed ??= {};

const flatten = (value) => {
  if (Array.isArray(value)) return value;
  if (Array.isArray(value?.body)) return value.body;
  return [value];
};

const decodeEntities = (s) => String(s ?? '')
  .replace(/&#(x[0-9a-f]+|\d+);/gi, (_, n) => {
    const cp = n[0].toLowerCase() === 'x' ? parseInt(n.slice(1), 16) : parseInt(n, 10);
    try { return String.fromCodePoint(cp); } catch { return ''; }
  })
  .replace(/&(amp|lt|gt|quot|apos|nbsp);/gi, (_, n) => ({
    amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  })[n.toLowerCase()]);

const stripTags = (s) => decodeEntities(String(s ?? '').replace(/<[^>]*>/g, ''));

const htmlToText = (html) => {
  let s = String(html ?? '');
  s = s.replace(/<a\b[^>]*href=(['"])(.*?)\1[^>]*>([\s\S]*?)<\/a>/gi, (_, _q, href, inner) => {
    const label = stripTags(inner).trim();
    const decodedHref = decodeEntities(href);
    if (label.startsWith('@') || label.startsWith('#')) return label;
    return /^https?:\/\//i.test(decodedHref) ? decodedHref : label;
  });
  s = s.replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p\s*>/gi, '\n\n')
    .replace(/<li\b[^>]*>/gi, '• ')
    .replace(/<\/li\s*>/gi, '\n')
    .replace(/<[^>]*>/g, '');
  return decodeEntities(s)
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
};

const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
const graphemes = (s) => Array.from(segmenter.segment(s), x => x.segment);

const splitText = (text) => {
  const all = graphemes(text);
  if (all.length <= 300) return [text];
  const limit = 292;
  const out = [];
  let rest = text.trim();
  while (graphemes(rest).length > limit) {
    const gs = graphemes(rest);
    const head = gs.slice(0, limit).join('');
    let cut = Math.max(head.lastIndexOf('\n\n'), head.lastIndexOf('\n'), head.lastIndexOf('. '), head.lastIndexOf(' '));
    if (cut < Math.floor(limit * 0.55)) cut = head.length;
    const piece = rest.slice(0, cut).trim();
    out.push(piece || head);
    rest = rest.slice(cut).trim();
  }
  if (rest) out.push(rest);
  return out.map((part, i) => part + '\n\n(' + (i + 1) + '/' + out.length + ')');
};

const rows = $input.all().flatMap(item => flatten(item.json));
const eligible = rows.filter(status => {
  if (!status?.id || status.visibility !== 'public') return false;
  if (status.reblog || status.in_reply_to_id) return false;
  const account = status.account ?? {};
  const acct = String(account.acct ?? '').replace(/^@/, '').toLowerCase();
  const username = String(account.username ?? '').toLowerCase();
  return username === cfg.fediUsername.toLowerCase() &&
    (acct === cfg.fediUsername.toLowerCase() || acct === cfg.fediAccount.toLowerCase());
}).sort((a, b) => new Date(a.created_at) - new Date(b.created_at));

if (!state.initialized && cfg.bootstrapMode === 'skip_existing') {
  for (const status of eligible) state.processed[String(status.id)] = new Date().toISOString();
  state.initialized = true;
  return [];
}

state.initialized = true;
const unseen = eligible.filter(status => !state.processed[String(status.id)]);

return unseen.map(status => {
  const content = htmlToText(status.content || status.text || '');
  const cw = htmlToText(status.spoiler_text || '');
  const text = cw ? '[CW: ' + cw + ']\n\n' + content : content;
  const images = (status.media_attachments ?? [])
    .filter(m => m?.type === 'image' && (m.url || m.remote_url))
    .slice(0, 4)
    .map((m, index) => ({
      index,
      url: m.url || m.remote_url,
      alt: String(m.description || '').trim(),
      mimeType: m.mime_type || '',
    }));
  const chunks = text ? splitText(text) : (images.length ? [''] : []);
  if (!chunks.length) throw new Error('Fediverse status ' + status.id + ' has neither publishable text nor images.');
  return {
    json: {
      sourceId: String(status.id),
      sourceUrl: status.url,
      sourceCreatedAt: status.created_at,
      chunks,
      images,
      droppedImageCount: Math.max(0, (status.media_attachments ?? []).filter(m => m?.type === 'image').length - 4),
      language: cfg.language,
    },
  };
});

const did = String($json.did || '');
let didDocumentUrl;

if (did.startsWith('did:plc:')) {
  didDocumentUrl = 'https://plc.directory/' + encodeURIComponent(did);
} else if (did.startsWith('did:web:')) {
  const parts = did.slice(8).split(':').map(decodeURIComponent);
  const host = parts.shift();
  if (!host || /[\\/@]/.test(host)) throw new Error('Unsafe did:web host: ' + host);
  didDocumentUrl = parts.length
    ? 'https://' + host + '/' + parts.map(encodeURIComponent).join('/') + '/did.json'
    : 'https://' + host + '/.well-known/did.json';
} else {
  throw new Error('Unsupported DID method: ' + did);
}

return [{ json: { did, didDocumentUrl } }];

const did = $('Build DID document URL').first().json.did;
const doc = $json;
if (doc.id && doc.id !== did) throw new Error('DID document id does not match resolved DID.');
const services = Array.isArray(doc.service) ? doc.service : [];
const service = services.find(s => {
  const types = Array.isArray(s.type) ? s.type : [s.type];
  return types.includes('AtprotoPersonalDataServer') || String(s.id || '').endsWith('#atproto_pds');
});
if (!service?.serviceEndpoint) throw new Error('No ATProto PDS service found in DID document.');
const endpointText = String(service.serviceEndpoint).trim();
if (!/^https:\/\//i.test(endpointText)) throw new Error('Refusing non-HTTPS PDS endpoint.');
const authority = endpointText.slice(8).split(/[/?#]/, 1)[0];
if (!authority || authority.includes('@') || /[\\\s]/.test(authority)) {
  throw new Error('Refusing invalid PDS endpoint.');
}
return [{ json: { did, pds: 'https://' + authority } }];

