parameters.jsCode:
const session = $json;
const resolved = $('Extract PDS endpoint').first().json;
const configuredHandle = $('Configuration').first().json.atprotoHandle;
if (!session.accessJwt) throw new Error('ATProto createSession returned no accessJwt.');
if (session.did !== resolved.did) {
  throw new Error('ATProto login DID does not match the resolved DID for ' + configuredHandle + '.');
}
return $('Select new public originals').all().map(item => ({
  json: {
    ...item.json,
    did: resolved.did,
    pds: resolved.pds,
    accessJwt: session.accessJwt,
  },
}));

const rows = $input.all().map(i => i.json);
return [{
  json: {
    ok: true,
    processedCount: rows.length,
    processed: rows,
    finishedAt: new Date().toISOString(),
  },
}];

const base = $json;
if (!base.images?.length) return [{ json: { ...base, hasMedia: false, media: null } }];
return base.images.map(media => ({
  json: { ...base, hasMedia: true, media },
}));

const cfg = $('Configuration').first().json;
const maxBytes = Number(cfg.imageMaxBytes || 1000000);
const items = $input.all();

for (let index = 0; index < items.length; index++) {
  const buffer = await this.helpers.getBinaryDataBuffer(index, 'data');
  if (!buffer.length) throw new Error('Image compression produced an empty file.');
  if (buffer.length > maxBytes) {
    const media = items[index].json.media || {};
    throw new Error(
      'Compressed image ' + ((media.index ?? index) + 1) +
      ' is still ' + buffer.length + ' bytes; limit is ' + maxBytes +
      '. Lower imageMaxDimension or imageJpegQuality in Configuration.'
    );
  }
  items[index].json = {
    ...items[index].json,
    compressedImageBytes: buffer.length,
    compressedImageMimeType: items[index].binary?.data?.mimeType || 'image/jpeg',
  };
}

return items;

const meta = $('Prepare image items').item.json;
if (!$json.blob) throw new Error('uploadBlob returned no blob for source status ' + meta.sourceId);
return {
  json: {
    ...meta,
    uploaded: { alt: meta.media.alt || '', image: $json.blob },
  },
};

const inputs = $input.all().map(i => i.json);
if (!inputs.length) return [];
const base = inputs[0];
const uploads = inputs
  .filter(x => x.uploaded)
  .sort((a, b) => a.media.index - b.media.index)
  .map(x => x.uploaded)
  .slice(0, 4);

const alphabet = '234567abcdefghijklmnopqrstuvwxyz';
const hash10 = (s) => {
  let h = 2166136261;
  for (const ch of String(s)) h = Math.imul(h ^ ch.codePointAt(0), 16777619);
  return (h >>> 0) & 1023;
};
const micros = (iso) => {
  const match = String(iso).match(/^(.*?\.)(\d+)(Z|[+-]\d\d:\d\d)$/);
  if (!match) return BigInt(Date.parse(iso)) * 1000n;
  const msBase = Date.parse(match[1] + match[2].slice(0, 3).padEnd(3, '0') + match[3]);
  return BigInt(msBase) * 1000n + BigInt(match[2].slice(3, 6).padEnd(3, '0'));
};
const tid = (iso, sourceId, index) => {
  let value = ((micros(iso) + BigInt(index)) << 10n) | BigInt(hash10(sourceId));
  let out = '';
  for (let i = 0; i < 13; i++) { out = alphabet[Number(value & 31n)] + out; value >>= 5n; }
  if (!/^[234567abcdefghij][234567abcdefghijklmnopqrstuvwxyz]{12}$/.test(out)) throw new Error('Generated invalid TID: ' + out);
  return out;
};

const state = $getWorkflowStaticData('global');
state.threadState ??= {};
state.threadState[base.sourceId] = { root: null, parent: null };

return base.chunks.map((text, index) => ({
  json: {
    sourceId: base.sourceId,
    sourceUrl: base.sourceUrl,
    sourceCreatedAt: base.sourceCreatedAt,
    language: base.language,
    did: base.did,
    pds: base.pds,
    accessJwt: base.accessJwt,
    text,
    index,
    total: base.chunks.length,
    rkey: tid(base.sourceCreatedAt, base.sourceId, index),
    uploadedImages: index === 0 ? uploads : [],
    droppedImageCount: base.droppedImageCount,
  },
}));

const rows = $input.all().map(i => i.json);
if (!rows.length) throw new Error('Thread loop completed without records.');
const first = rows[0];
const state = $getWorkflowStaticData('global');
state.processed ??= {};
state.processed[first.sourceId] = new Date().toISOString();
delete state.threadState?.[first.sourceId];

const entries = Object.entries(state.processed).sort((a, b) => String(b[1]).localeCompare(String(a[1])));
const keep = $('Configuration').first().json.maxProcessedIds;
state.processed = Object.fromEntries(entries.slice(0, keep));

return [{
  json: {
    sourceId: first.sourceId,
    sourceUrl: first.sourceUrl,
    threadParts: rows.length,
    rootUri: rows[0].createdRef.uri,
    imagesUploaded: first.uploadedImages?.length || 0,
    imagesDroppedBecauseAtProtoLimitIsFour: first.droppedImageCount || 0,
  },
}];

const item = $json;
const staticData = $getWorkflowStaticData('global');
staticData.threadState ??= {};
const thread = staticData.threadState[item.sourceId] ?? { root: null, parent: null };

const byteLength = (s) => Buffer.from(s, 'utf8').length;
const ranges = [];
const addFacet = (start, end, feature) => {
  if (ranges.some(r => start < r.end && end > r.start)) return;
  ranges.push({ start, end });
  facets.push({
    index: { byteStart: byteLength(item.text.slice(0, start)), byteEnd: byteLength(item.text.slice(0, end)) },
    features: [feature],
  });
};

const facets = [];
const urlRe = /https?:\/\/[^\s<>"']+/gu;
for (const match of item.text.matchAll(urlRe)) {
  let value = match[0].replace(/[),.;:!?]+$/u, '');
  if (!value) continue;
  addFacet(match.index, match.index + value.length, { '$type': 'app.bsky.richtext.facet#link', uri: value });
}
const tagRe = /#[\p{L}\p{N}_]+/gu;
for (const match of item.text.matchAll(tagRe)) {
  const tag = match[0].slice(1);
  if (Array.from(new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(tag)).length > 64) continue;
  addFacet(match.index, match.index + match[0].length, { '$type': 'app.bsky.richtext.facet#tag', tag });
}
facets.sort((a, b) => a.index.byteStart - b.index.byteStart);

const record = {
  '$type': 'app.bsky.feed.post',
  text: item.text,
  createdAt: new Date(Date.parse(item.sourceCreatedAt) + item.index).toISOString(),
};
if (facets.length) record.facets = facets;
if (item.language) record.langs = [item.language];
if (item.uploadedImages?.length) {
  record.embed = { '$type': 'app.bsky.embed.images', images: item.uploadedImages };
}
if (item.index > 0) {
  if (!thread.root || !thread.parent) throw new Error('Missing root/parent for thread part ' + (item.index + 1));
  record.reply = { root: thread.root, parent: thread.parent };
}

return {
  json: {
    ...item,
    request: {
      repo: item.did,
      collection: 'app.bsky.feed.post',
      rkey: item.rkey,
      validate: true,
      record,
    },
  },
};

const sent = $('Build ATProto post record').item.json;
if (!$json.uri || !$json.cid) throw new Error('putRecord returned no strong reference.');
const ref = { uri: $json.uri, cid: $json.cid };
const state = $getWorkflowStaticData('global');
state.threadState ??= {};
const thread = state.threadState[sent.sourceId] ?? { root: null, parent: null };
if (sent.index === 0) thread.root = ref;
thread.parent = ref;
state.threadState[sent.sourceId] = thread;
return { json: { ...sent, createdRef: ref } };
